package servers_test

import (
	"path/filepath"
	"reflect"
	"regexp"
	"sort"
	"strings"
	"testing"

	"github.com/goceleris/probatorium/servers"
)

// THROWAWAY (ab/c1-harness-h7fix-20261105, not for merge). Pins the ARMED columns of the H7' collector (servers/c1pp_arms.go, generated by pp-gen.py; review r5 P1): the celeris adapter whose
// registry env carries PROBATORIUM_PPROF=<mode>. The collector watches the FIRST measurement window of a column, so the property that matters is that the dispatch glob of an armed column
// selects exactly ONE scenario, the family's cell; the table below states the cells (the diagnostic windows of celeris#854 and #857), not derived from the generated file.

var c1ppCells = map[string]string{"dump": "driver-redis-pipeline", "profile": "driver-mc-get"}

type c1ppCol struct{ name, mode, arm, engine string }

func c1ppCols(t *testing.T) []c1ppCol {
	t.Helper()
	re := regexp.MustCompile(`^c1pp-(dump|profile)-r(\d)-(main|v1511)-([a-z0-9+-]+)$`)
	var cols []c1ppCol
	for name := range servers.Registry {
		if !strings.HasPrefix(name, "c1pp-") {
			continue
		}
		m := re.FindStringSubmatch(name)
		if m == nil {
			t.Errorf("column %s does not match c1pp-<dump|profile>-r<rep>-<main|v1511>-<engine>", name)
			continue
		}
		cols = append(cols, c1ppCol{name, m[1], m[3], m[4]})
	}
	sort.Slice(cols, func(i, j int) bool { return cols[i].name < cols[j].name })
	if len(cols) == 0 {
		t.Fatal("no c1pp column in the registry")
	}
	return cols
}

func TestC1PPColumnsAreTheArmedTwinsOfTheUnarmedOnes(t *testing.T) {
	mainPin, basePin := celerisRequire(t, "celeris"), celerisRequire(t, "celeris_v1511")
	for _, c := range c1ppCols(t) {
		a := servers.Registry[c.name]
		base, ok := servers.Registry["celeris-"+c.engine]
		if !ok {
			t.Errorf("%s: no unarmed twin celeris-%s", c.name, c.engine)
			continue
		}
		gb := a.Bin.(servers.GoBinary)
		wantMod, wantVer := "servers/celeris", mainPin
		if c.arm == "v1511" {
			wantMod, wantVer = "servers/celeris_v1511", basePin
		}
		if gb.ModuleDir != wantMod || a.FrameworkVersion != wantVer {
			t.Errorf("%s: module %s version %s, want %s %s (the go.mod pins)", c.name, gb.ModuleDir, a.FrameworkVersion, wantMod, wantVer)
		}
		if a.Framework != "celeris-armed-"+c.mode+"-"+c.arm {
			t.Errorf("%s: framework %q (never \"celeris\": the report builders stamp the main pin on it)", c.name, a.Framework)
		}
		// the ONLY env is the gate, with the mode; no knob, no IRQ key: the arm is the unarmed column plus the gate
		if !reflect.DeepEqual(a.SUTEnv, map[string]string{"PROBATORIUM_PPROF": c.mode}) {
			t.Errorf("%s: env %v, want exactly PROBATORIUM_PPROF=%s", c.name, a.SUTEnv, c.mode)
		}
		norm := a
		norm.Name, norm.Framework, norm.FrameworkVersion, norm.Bin, norm.SUTEnv = base.Name, base.Framework, base.FrameworkVersion, base.Bin, base.SUTEnv
		if !reflect.DeepEqual(norm, base) {
			t.Errorf("%s differs from celeris-%s in more than Name/Framework/Version/Bin/SUTEnv", c.name, c.engine)
		}
		if strings.Contains(c.name, "io512") {
			t.Errorf("%s: io512 would switch the 90 s window on", c.name)
		}
	}
}

// The window property: for every mode, cells=<cell>/c1pp-<mode>-* selects every armed column of that mode with exactly one scenario, the family's cell. The collector then watches the
// right window by construction. A glob over several cells (the plan's LF-1 selection driver-redis-pipeline/* + driver-mc-*) would put the armed column's first window on driver-mc-get.
func TestC1PPGlobSelectsTheOneWindowTheCollectorWatches(t *testing.T) {
	cols := c1ppCols(t)
	for mode, cell := range c1ppCells {
		want := 0
		for _, c := range cols {
			if c.mode == mode {
				want++
			}
		}
		if want == 0 {
			t.Errorf("no %s columns", mode)
			continue
		}
		got := p2Matched(t, cell+"/c1pp-"+mode+"-*")
		if len(got) != want {
			t.Errorf("%s: the glob selects %d columns, want %d", mode, len(got), want)
		}
		for c, sc := range got {
			if len(sc) != 1 || sc[0] != cell {
				t.Errorf("%s: column %s matches scenarios %v, want exactly [%s]", mode, c, sc, cell)
			}
		}
		// the wide LF-1 style glob gives each armed column MORE than one scenario: exactly the case the cells list must avoid
		wide := p2Matched(t, "driver-*/c1pp-"+mode+"-*")
		multi := 0
		for _, sc := range wide {
			if len(sc) > 1 {
				multi++
			}
		}
		if multi == 0 {
			t.Logf("%s: a wide driver-* glob also selects one scenario per column here", mode)
		}
	}
	// no unarmed glob of the diagnostic dispatches selects an armed column, and no other family's glob does
	for _, g := range []string{"driver-redis-pipeline/celeris-*", "driver-mc-get/celeris-*", "driver-mc-get/baseline-*", "ws-hub-broadcast-128/c2lad-*", "get-simple-512c/c1arm-*-io512"} {
		for c := range p2Matched(t, g) {
			if strings.HasPrefix(c, "c1pp-") {
				t.Errorf("the glob %q selects the armed column %s", g, c)
			}
		}
	}
	for c := range p2Matched(t, "driver-redis-pipeline/c1pp-dump-*") {
		if strings.HasPrefix(c, "c1pp-profile-") {
			t.Errorf("the dump glob selects the profile column %s", c)
		}
	}
}

func TestC1PPModulesExist(t *testing.T) {
	for _, c := range c1ppCols(t) {
		gb := servers.Registry[c.name].Bin.(servers.GoBinary)
		if readFile(t, "..", gb.ModuleDir, "go.mod") == "" {
			t.Errorf("%s: %s has no go.mod", c.name, filepath.Base(gb.ModuleDir))
		}
		// both modules carry the gate's implementation
		if !strings.Contains(readFile(t, "..", gb.ModuleDir, "pprof_sidecar.go"), `const pprofEnv = "PROBATORIUM_PPROF"`) {
			t.Errorf("%s: %s does not read PROBATORIUM_PPROF", c.name, gb.ModuleDir)
		}
	}
}
